#include "stdlib/blas/ext/base/ndarray/dcartesian_power.h"
#include "stdlib/blas/ext/base/dcartesian_power.h"
#include "stdlib/ndarray/ctor.h"
#include <stdint.h>

/**
* Computes the Cartesian power for a double-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional output ndarray.
*     -   a zero-dimensional ndarray specifying the power.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_dcartesian_power( const struct ndarray *arrays[] ) {
	int64_t N;
	int32_t k;
	double *X;
	double *Out;
	int64_t strideX;
	int64_t offsetX;
	int64_t strideOut1;
	int64_t strideOut2;
	int64_t offsetOut;

	N = stdlib_ndarray_dimension( arrays[ 0 ], 0 );

	int32_t *k_data = (int32_t *)( stdlib_ndarray_data( arrays[ 2 ] ) + stdlib_ndarray_offset( arrays[ 2 ] ) );
	k = k_data[ 0 ];

	X = (double *)stdlib_ndarray_data( arrays[ 0 ] );
	strideX = stdlib_ndarray_stride_elements( arrays[ 0 ], 0 );
	offsetX = stdlib_ndarray_offset_elements( arrays[ 0 ] );

	Out = (double *)stdlib_ndarray_data( arrays[ 1 ] );
	strideOut1 = stdlib_ndarray_stride_elements( arrays[ 1 ], 0 );
	strideOut2 = stdlib_ndarray_stride_elements( arrays[ 1 ], 1 );
	offsetOut = stdlib_ndarray_offset_elements( arrays[ 1 ] );

	stdlib_strided_dcartesian_power_ndarray( N, k, X, strideX, offsetX, Out, strideOut1, strideOut2, offsetOut );
}
